//! The Domainator Viewer page: one self-contained HTML file that opens the network, tree
//! and projection bundles (`.dvb`, [`super::viewer_bundle`]) and the older network
//! bundles (`.dsnv`).
//!
//! Mirrors `domainator.viewer_html`. The page is upstream's own: the shell in
//! `assets/viewer_shell.html` is the render of `viewer_html(title, embedded_bundle=None)`
//! with its two interpolation points frozen into tokens, plus the GUI host hook. It is
//! generated by `scripts/regen_viewer_shell.py` and never hand-edited.

use crate::tools::report_html::{base64_encode, html_escape};

/// The viewer app's own name, as upstream spells it.
pub const VIEWER_APP_NAME: &str = "Domainator Viewer";

/// The shell, as `scripts/regen_viewer_shell.py` writes it.
const SHELL: &str = include_str!("../../assets/viewer_shell.html");

/// The shell's bundle slot when nothing is embedded: a key of its `viewer-config` block,
/// written by `json.dumps` with the default `": "` separator.
const EMBEDDED_BUNDLE_NULL: &str = "\"embeddedBundleBase64\": null";

/// The page's `<h1>`: the app name, plus the bundle's name when there is one.
///
/// Mirrors `viewer_html.viewer_heading`. Titles that name nothing in particular collapse
/// to the bare app name rather than rendering "`<app name>: <app name>`"; the older app
/// names are included so bundles written under them behave the same. Upstream applies
/// this at render time, which a frozen template token cannot do — hence the
/// `heading-token` local patch in `scripts/regen_viewer_shell.py`.
pub fn viewer_heading(name: &str) -> String {
    let name = name.trim();
    const GENERIC: [&str; 4] = [
        "",
        VIEWER_APP_NAME,
        "Domainator Similarity Network Viewer",
        "Domainator SSN Viewer",
    ];
    if GENERIC.contains(&name) {
        VIEWER_APP_NAME.to_string()
    } else {
        format!("{VIEWER_APP_NAME}: {name}")
    }
}

/// The viewer page (`viewer_html`), optionally with a bundle file's bytes
/// (gzip-compressed JSON) embedded so that it opens with it. Without one, the page opens
/// bundles chosen in it.
pub fn render_html(title: &str, embedded_bundle_gzip: Option<&[u8]>) -> String {
    let mut html = SHELL
        .replace("@@VIEWER_TITLE@@", &html_escape(title))
        .replace("@@VIEWER_HEADING@@", &html_escape(&viewer_heading(title)));
    // The key sits in the page's `viewer-config` JSON block; base64 needs no JSON
    // escaping and holds no `<`, so it cannot close the `<script>` element.
    if let Some(gz) = embedded_bundle_gzip {
        let b64 = base64_encode(gz);
        html = html.replacen(
            EMBEDDED_BUNDLE_NULL,
            &format!("\"embeddedBundleBase64\": \"{b64}\""),
            1,
        );
    }
    html
}

/// The page's size with `embedded_bundle_len` bytes of bundle embedded in base64, which
/// is what the output size limit is checked against before it is built.
pub fn projected_html_bytes(embedded_bundle_len: usize) -> u64 {
    (embedded_bundle_len as u64) * 4 / 3
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn html_render_substitutes_tokens() {
        let html = render_html("My <SSN>", None);
        assert!(html.contains("<title>My &lt;SSN&gt;</title>"));
        assert!(!html.contains("@@VIEWER_TITLE@@"));
        assert!(!html.contains("@@VIEWER_HEADING@@"));
        // A named bundle gets "<app>: <name>"; the escaping applies to the heading too.
        assert!(html.contains("Domainator Viewer: My &lt;SSN&gt;"));
        assert_eq!(html.matches(EMBEDDED_BUNDLE_NULL).count(), 1);
        // A title naming nothing in particular collapses to the bare app name, including
        // the app's two earlier names.
        for generic in [
            "",
            "  ",
            "Domainator SSN Viewer",
            "Domainator Similarity Network Viewer",
            VIEWER_APP_NAME,
        ] {
            assert_eq!(viewer_heading(generic), VIEWER_APP_NAME);
        }
        assert_eq!(viewer_heading("FeSOD"), "Domainator Viewer: FeSOD");

        let html2 = render_html("x", Some(b"gzipbytes"));
        assert!(html2.contains("\"embeddedBundleBase64\": \"Z3ppcGJ5dGVz\""));
        assert!(!html2.contains(EMBEDDED_BUNDLE_NULL));
    }

    #[test]
    fn the_gui_host_hook_is_in_the_shell() {
        // The GUI's viewer tab drives "Extract selected" from this message; the shell is
        // regenerated from upstream, and the hook is a local patch that must survive it.
        assert_eq!(SHELL.matches("domainator-viewer-selection").count(), 1);
    }
}
